local GEMINI_MODELS = { "gemini-3.5-flash-lite", "gemini-flash-lite-latest" }
local GEMINI_TIMEOUT = 20

local function geminiOnce(model, system, prompt, temperature, maxTokens)
    local ok, res = pcall(httpRequest, {
        Url = GEMINI_MODELS_URL .. "/" .. model .. ":generateContent",
        Method = "POST",
        Headers = { ["Content-Type"] = "application/json", ["x-goog-api-key"] = settings.geminiKey },
        Body = ConfigHttp:JSONEncode({
            system_instruction = { parts = { { text = system } } },
            contents = { { role = "user", parts = { { text = prompt } } } },
            generationConfig = {
                temperature = temperature,
                maxOutputTokens = maxTokens,
                thinkingConfig = { thinkingLevel = "minimal" },
            },
        }),
    })
    if not ok or type(res) ~= "table" then return nil, "Request failed" end
    local data
    pcall(function() data = ConfigHttp:JSONDecode(res.Body or res.body) end)
    local status = tonumber(res.StatusCode or res.Status or res.status_code)
    if type(data) == "table" and type(data.error) == "table" then
        return nil, tostring(data.error.message or status), status == 401 or status == 403
    end
    local candidate = type(data) == "table" and type(data.candidates) == "table" and data.candidates[1]
    local content = type(candidate) == "table" and candidate.content
    local partsList = type(content) == "table" and content.parts
    local reply = ""
    if type(partsList) == "table" then
        for _, part in ipairs(partsList) do
            if type(part) == "table" and type(part.text) == "string" and not part.thought then
                reply = reply .. part.text
            end
        end
    end
    if reply == "" then return nil, "No answer" end
    return reply
end
local function geminiGenerate(system, prompt, temperature, maxTokens)
    if not httpRequest then return nil, "Executor has no HTTP request" end
    local result, lastErr, pending = nil, "No answer", #GEMINI_MODELS
    for _, model in ipairs(GEMINI_MODELS) do
        task.spawn(function()
            local reply, err, fatal = geminiOnce(model, system, prompt, temperature, maxTokens)
            pending -= 1
            if reply and not result then
                result = reply
            elseif err then
                lastErr = err
                if fatal then pending = 0 end
            end
        end)
    end
    local deadline = os.clock() + GEMINI_TIMEOUT
    while not result and pending > 0 and os.clock() < deadline do task.wait() end
    if result then return result end
    return nil, pending > 0 and "Timed out" or lastErr
end
pcall(function()
    if not (isfile and readfile) then return end
    local raw
    for _, fileName in ipairs({ CONFIG_FILE, LEGACY_CONFIG_FILE }) do
        if isfile(fileName) then
            raw = readfile(fileName)
            break
        end
    end
    if not raw then return end
    local saved = ConfigHttp:JSONDecode(raw)
    for key, kind in pairs(PERSISTED) do
        if type(saved[key]) == kind then settings[key] = saved[key] end
    end
    settings.submitAfter = math.clamp(math.floor(settings.submitAfter), 1, 5)
    local key = type(saved.toggleKey) == "string" and Enum.KeyCode[saved.toggleKey]
    if key then settings.toggleKey = key end
    if type(saved.triggers) == "table" then
        local list, has = {}, {}
        for _, word in ipairs(saved.triggers) do
            if type(word) == "string" and word ~= "" then
                list[#list + 1] = word
                has[word] = true
            end
        end
        if not saved.riddleDefaultsMerged then
            for _, word in ipairs({ "question is", "riddle is", "the riddle is", "riddle:", "use riddle" }) do
                if not has[word] then list[#list + 1] = word end
            end
        end
        settings.triggers = list
    end
end)

local function looseText(text)
    local out, map = {}, {}
    local gap = false
    for i = 1, #text do
        local ch = text:sub(i, i)
        if ch:match("%w") or ch == ":" then
            if gap and ch ~= ":" and #out > 0 then
                out[#out + 1] = " "
                map[#out] = i
            end
            gap = false
            out[#out + 1] = ch:lower()
            map[#out] = i
        else
            gap = true
        end
    end
    return table.concat(out), map
end

local sortedTriggers = {}
local function rebuildTriggerCache()
    sortedTriggers = {}
    for _, t in ipairs(settings.triggers) do
        local loose = looseText(t)
        if loose ~= "" then sortedTriggers[#sortedTriggers + 1] = loose end
    end
    table.sort(sortedTriggers, function(a, b) return #a > #b end)
end
rebuildTriggerCache()

local savePending = false
local function writeConfig()
    if not writefile then return end
    pcall(function()
        local out = { version = 3, toggleKey = settings.toggleKey.Name, triggers = settings.triggers, riddleDefaultsMerged = true }
        for key in pairs(PERSISTED) do out[key] = settings[key] end
        local encoded = ConfigHttp:JSONEncode(out)
        writefile(CONFIG_FILE, encoded)
        -- Keep the old filename readable by older copies of the script.
        writefile(LEGACY_CONFIG_FILE, encoded)
    end)
end
local function saveSettings()
    if not writefile or savePending then return end
    savePending = true
    task.delay(1, function()
        savePending = false
        writeConfig()
    end)
end

