local function log(message, kind, rich)
    task.defer(function()
        print("[SKIBIDI CODE REDEEMER] [" .. os.date("%H:%M:%S") .. "] " .. (tostring(message):gsub("<[^>]->", "")))
        order += 1
        total += 1
        local entry = box({ LayoutOrder = order, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, Parent = console })
        local stamp = text({ Text = os.date("%H:%M"), FontFace = F.Mono, TextSize = 12, TextColor3 = C.Faint,
            TextTransparency = 1, Size = UDim2.fromOffset(40, 16), Parent = entry })
        local body = text({ Text = rich and message or esc(message), RichText = true, TextWrapped = true,
            FontFace = F.Book, TextSize = 13, TextColor3 = KIND_COLOR[kind] or C.Text, TextTransparency = 1,
            TextYAlignment = Enum.TextYAlignment.Top, Position = UDim2.fromOffset(52, 0),
            Size = UDim2.new(1, -52, 0, 16), AutomaticSize = Enum.AutomaticSize.Y, Parent = entry })
        tween(stamp, 0.35, { TextTransparency = 0 })
        tween(body, 0.35, { TextTransparency = 0 })
        entries[#entries + 1] = entry
        if #entries > 80 then
            local oldest = entries[1]
            table.move(entries, 2, #entries, 1)
            entries[#entries] = nil
            oldest:Destroy()
        end
        emptyText.Visible = false
        updateCount()
    end)
end

local function logCode(code, prefix, kind)
    local chip = '<font face="RobotoMono">' .. esc(code) .. "</font>"
    log((prefix and (esc(prefix) .. "  ") or "") .. chip, kind or "code", true)
end

