local BUY_RANGE, BUY_INTERVAL = 15, 0.08
local HOLD_INPUTS = { Enum.UserInputType.Keyboard, Enum.UserInputType.MouseButton1, Enum.UserInputType.Touch }
local prompts, promptConn, buyThread = {}, nil, nil

local function promptPosition(p)
    local parent = p.Parent
    if parent and parent:IsA("Attachment") and parent.Parent and parent.Parent:IsA("BasePart") then return parent.Parent.Position end
    if parent and parent:IsA("BasePart") then return parent.Position end
    if parent and parent:IsA("Model") and parent.PrimaryPart then return parent.PrimaryPart.Position end
end
local function holdPrompt(p)
    pcall(function() if fireproximityprompt then fireproximityprompt(p) end end)
    for _, input in ipairs(HOLD_INPUTS) do pcall(function() p:InputHoldBegin(input) end) end
end
local function releasePrompt(p)
    for _, input in ipairs(HOLD_INPUTS) do pcall(function() p:InputHoldEnd(input) end) end
end
local function autobuyTick()
    local root = player.Character and player.Character:FindFirstChild("HumanoidRootPart")
    if not root then return end
    for p in pairs(prompts) do
        local pos = p.Parent and p.Enabled and promptPosition(p)
        if not pos then
            prompts[p] = nil
        elseif (root.Position - pos).Magnitude <= BUY_RANGE then
            holdPrompt(p)
        else
            releasePrompt(p)
        end
    end
end
local function stopAutobuy()
    if promptConn then promptConn:Disconnect() promptConn = nil end
    if buyThread then task.cancel(buyThread) buyThread = nil end
    for p in pairs(prompts) do releasePrompt(p) end
    prompts = {}
end
local function startAutobuy()
    stopAutobuy()
    for _, obj in ipairs(workspace:GetDescendants()) do
        if obj:IsA("ProximityPrompt") then prompts[obj] = true end
    end
    promptConn = workspace.DescendantAdded:Connect(function(obj)
        if obj:IsA("ProximityPrompt") then prompts[obj] = true end
    end)
    buyThread = task.spawn(function()
        while settings.autobuy do
            task.wait(BUY_INTERVAL)
            pcall(autobuyTick)
        end
    end)
end

