local function renderKeyStatus()
    if hasGeminiKey() then
        keyStatus.Text = UI.AI.active().name .. " connected · " .. maskKey(UI.AI.key())
        keyStatus.TextColor3 = C.Green
        disconnectBtn.Visible = true
    else
        keyStatus.Text = "Not connected"
        keyStatus.TextColor3 = C.Faint
        disconnectBtn.Visible = false
    end
end
renderKeyStatus()
setConnectBtnState(hasGeminiKey())

local function verifyGeminiKey(key)
    if not httpRequest then return nil, "Executor has no HTTP request" end
    local prov = UI.AI.active()
    if prov.base then
        local ok, res = pcall(httpRequest, { Url = prov.base .. "/models", Method = "GET", Headers = { ["Authorization"] = "Bearer " .. key } })
        if not ok or type(res) ~= "table" then return nil, "Request failed" end
        local status = tonumber(res.StatusCode or res.Status or res.status_code)
        if status == 200 or status == 429 then return true end
        if status == 400 or status == 401 or status == 403 then return false, "Invalid key" end
        return nil, prov.name .. " returned " .. tostring(status)
    end
    local ok, res = pcall(httpRequest, { Url = GEMINI_MODELS_URL, Method = "GET", Headers = { ["x-goog-api-key"] = key } })
    if not ok then return nil, "Request failed" end
    if type(res) ~= "table" then return nil, tostring(res) end
    local status = tonumber(res.StatusCode or res.Status or res.status_code)
    if status == 200 or status == 429 then return true end
    if status == 400 or status == 401 or status == 403 then return false, "Invalid key" end
    return nil, "Google returned " .. tostring(status)
end

local checkingKey = false
local function connectKey()
    if checkingKey then return end
    local key = keyInput.Text:gsub("%s", "")
    if key == "" then return end
    checkingKey = true
    keyStatus.Text = "Checking key..."
    keyStatus.TextColor3 = C.Sub
    task.spawn(function()
        local valid, err = verifyGeminiKey(key)
        checkingKey = false
        if valid then
            keyInput.Text = ""
            changed(UI.AI.active().key, key)
            renderKeyStatus()
            setConnectBtnState(true)
            log(UI.AI.active().name .. " key connected", "good")
            toast(UI.AI.active().name .. " connected", maskKey(key), true)
        else
            keyStatus.Text = err or "Invalid key"
            keyStatus.TextColor3 = C.Red
            toast("Key not accepted", err or "Invalid key", false, "warn")
        end
    end)
end
on(connectBtn.Activated, connectKey)
on(keyInput.FocusLost, function(enter) if enter then connectKey() end end)

on(disconnectBtn.Activated, function()
    changed(UI.AI.active().key, "")
    if settings.riddleSolver then
        setRiddleSwitch(false)
        changed("riddleSolver", false)
    end
    renderKeyStatus()
    setConnectBtnState(false)
    log(UI.AI.active().name .. " key removed", "sys")
end)

