local renderTriggers
local function removeTrigger(word)
    for i, w in ipairs(settings.triggers) do
        if w == word then table.remove(settings.triggers, i) break end
    end
    rebuildTriggerCache()
    saveSettings()
    renderTriggers()
end
renderTriggers = function()
    for _, child in ipairs(triggerList:GetChildren()) do
        if child:IsA("Frame") then child:Destroy() end
    end
    if #settings.triggers == 0 then
        local empty = box({ Size = UDim2.new(1, 0, 0, 32), Parent = triggerList })
        text({ Text = "No triggers, sniping is off", FontFace = F.Book, TextSize = 13, TextColor3 = C.Faint,
            Size = UDim2.fromScale(1, 1), Parent = empty })
        return
    end
    for i, word in ipairs(settings.triggers) do
        local row = box({ LayoutOrder = i, Size = UDim2.new(1, -4, 0, 32), BackgroundColor3 = C.Panel, Parent = triggerList }, { corner(4) })
        text({ Text = word, FontFace = F.Mono, TextSize = 12, TextTruncate = Enum.TextTruncate.AtEnd,
            Position = UDim2.fromOffset(12, 0), Size = UDim2.new(1, -56, 1, 0), Parent = row })
        local remove = button({
            Text = "Remove", FontFace = F.Medium, TextSize = 12, TextColor3 = C.Faint,
            TextXAlignment = Enum.TextXAlignment.Right,
            AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -12, 0, 0), Size = UDim2.fromOffset(60, 32),
            Parent = row,
        })
        remove.MouseEnter:Connect(function() tween(remove, 0.15, { TextColor3 = C.Red }) end)
        remove.MouseLeave:Connect(function() tween(remove, 0.2, { TextColor3 = C.Faint }) end)
        remove.Activated:Connect(function() removeTrigger(word) end)
    end
end

local function addTrigger()
    local word = (triggerInput.Text:lower():match("^%s*(.-)%s*$") or "")
    triggerInput.Text = ""
    if word == "" then return end
    for _, w in ipairs(settings.triggers) do
        if w == word then return end
    end
    table.insert(settings.triggers, word)
    rebuildTriggerCache()
    saveSettings()
    renderTriggers()
    log("Trigger added: " .. word, "sys")
end
on(addBtn.Activated, addTrigger)
on(triggerInput.FocusLost, function(enter) if enter then addTrigger() end end)
renderTriggers()


on(pill.InputBegan, function(input)
