local function renderArmed(animate)
    local t = animate and 0.25 or 0
    local armed = settings.armed
    pillText.Text = armed and "Armed" or "Idle"
    tween(dot, t, { BackgroundColor3 = armed and C.Green or C.Faint })
    tween(pillText, t, { TextColor3 = armed and C.Text or C.Sub })
end
local ringPhase = 0
tickers[#tickers + 1] = function(dt)
    if settings.armed then
        ringPhase = (ringPhase + dt / 1.8) % 1
        local size = 6 + 10 * ringPhase
        ring.Size = UDim2.fromOffset(size, size)
        ring.BackgroundTransparency = 0.5 + 0.5 * ringPhase
    else
        ring.BackgroundTransparency = 1
    end
end
renderArmed(false)

function UI.setArmed(value, silent)
    if settings.armed == value then return end
    changed("armed", value)
    renderArmed(true)
    if not silent then
        log(value and "Sniper armed" or "Sniper idle", value and "good" or "sys")
        assistant.event(value and "armed" or "idle")
    end
end
on(pill.Activated, function() UI.setArmed(not settings.armed) end)

local function selectPage(name, animate)
    if currentPage == name then return end
    currentPage = name
    title.Text = name
    for n, nav in pairs(navs) do
        local active = n == name
        tween(nav.button, animate and 0.2 or 0, { BackgroundColor3 = active and C.Raise or C.Panel })
        paint(nav.frames, active and C.Text or C.Faint, animate and 0.2 or 0)
    end
    tween(indicator, animate and 0.35 or 0, { Position = UDim2.fromOffset(0, navs[name].y + 10) })
    for n, p in pairs(pages) do p.Visible = n == name end
    if animate then
        pages[name].Position = UDim2.fromOffset(0, 10)
        tween(pages[name], 0.35, { Position = UDim2.fromOffset(0, 0) })
    end
end

for i, def in ipairs({ { "Sniper", ICONS.sniper }, { "Logs", ICONS.activity }, { "Riddle", ICONS.riddle }, { "Admin abuse helper", ICONS.admin }, { "Triggers", ICONS.triggers }, { "Settings", ICONS.settings } }) do
    local y = 68 + (i - 1) * 40
    local b, frames = iconButton(y, def[2])
    navs[def[1]] = { button = b, frames = frames, y = y }
    on(b.MouseEnter, function()
        if currentPage ~= def[1] then tween(b, 0.15, { BackgroundColor3 = C.Hover }); paint(frames, C.Sub, 0.15) end
    end)
    on(b.MouseLeave, function()
        if currentPage ~= def[1] then tween(b, 0.2, { BackgroundColor3 = C.Panel }); paint(frames, C.Faint) end
    end)
    on(b.Activated, function() selectPage(def[1], true) end)
end
selectPage("Sniper", false)

local collapseBtn, collapseFrames = iconButton(H - 46, ICONS.collapse)
