end
on(askBox.FocusLost, function(enter)
    local question = clean(askBox.Text)
    askBox.Visible = false
    historyFrame.Visible = false
    asking = false
    if enter and question ~= "" then
        answer(question)
    elseif not talking then
        bubble.Visible = false
    end
    pump()
end)

