local cleanups = {}

;(function()
local ReplicatedStorage = cloneref(game:GetService("ReplicatedStorage"))
local HttpService = cloneref(game:GetService("HttpService"))

local RIDDLE_TRIGGERS = {
    ["question is"]   = true,
    ["riddle is"]     = true,
    ["the riddle is"] = true,
    ["riddle:"]       = true,
    ["use riddle"]    = true,
}
local TYPE_DELAY = 0


local function stripRich(s)
    return (tostring(s or ""):gsub("<[^>]->", ""))
end
local function trim(s)
    return s:match("^%s*(.-)%s*$") or ""
end
local function cleanCode(s)
    s = tostring(s or "")
    if #s <= 50 and s:match("^%w+$") then return s end
    return (s:gsub("[^%w]", "")):sub(1, 50)
end

local codeUI
local function debugSource(fn)
    local ok, source = pcall(function() return debug.info(fn, "s") end)
    return ok and tostring(source or "") or ""
end

local function resolveCodeUI()
    if codeUI and codeUI.box and codeUI.box.Parent then
        return codeUI
    end
    codeUI = nil
    pcall(function()
        local pg = player:FindFirstChildOfClass("PlayerGui")
        local codesGui = pg and pg:FindFirstChild("Codes")
        if not codesGui then return end
        pcall(function() codesGui.Enabled = true end)
        local root = codesGui:FindFirstChild("Codes")
        if not root then return end
        local parent = root
        while parent do
            pcall(function() if parent:IsA("GuiObject") then parent.Visible = true end end)
            parent = parent.Parent
            if parent == codesGui then break end
        end
        local redeemFrame = root:FindFirstChild("CodeRedeem")
        local box = redeemFrame and redeemFrame:FindFirstChild("TextBox", true)
            or root:FindFirstChildWhichIsA("TextBox", true)
        if not box then return end
        local confirm = root:FindFirstChild("Confirm")
        local btn = confirm and confirm:FindFirstChildWhichIsA("GuiButton", true)
            or confirm
        for _, candidate in ipairs(root:GetDescendants()) do
            if btn then break end
            if candidate:IsA("GuiButton") then
                local label = (tostring(candidate.Name) .. " " .. tostring(candidate.Text or "")):lower()
                if label:find("submit", 1, true) or label:find("redeem", 1, true)
                    or label:find("confirm", 1, true) or label:find("claim", 1, true) then
                    btn = candidate
                    break
                end
            end
        end
        codeUI = { box = box, btn = btn }
    end)
    return codeUI
end
local resolveUI = resolveCodeUI

local fireButton
local function fireFocusLost(box)
    if not box then return false end
    local fired = false
    local ok, list = pcall(getconnections, box.FocusLost)
    if ok then
        for _, c in ipairs(list or {}) do
            pcall(function()
                local fn = c.Function
                if type(fn) == "function" and debug then
                    if type(debug.getupvalues) == "function" then
                        for i, value in pairs(debug.getupvalues(fn) or {}) do
                            if type(value) == "boolean" then debug.setupvalue(fn, i, false) end
                        end
                    elseif type(debug.getupvalue) == "function" then
                        for i = 1, 64 do
                            local name, value = debug.getupvalue(fn, i)
                            if not name then break end
                            if type(value) == "boolean" then debug.setupvalue(fn, i, false) end
                        end
                    end
                end
                if type(c.Fire) == "function" then c:Fire(true) fired = true end
            end)
        end
    end
    if not fired and typeof(firesignal) == "function" then
        fired = pcall(firesignal, box.FocusLost, true)
    end
    return fired
end

local function submitFast(code)
    local ui = resolveUI()
    if not ui or not ui.box then return false end
    code = cleanCode(code)
    for _ = 1, 8 do
        local ok = pcall(function()
            ui.box:CaptureFocus()
            ui.box.Text = code
        end)
        if ok and ui.box.Text == code then break end
        task.wait(0.03)
    end
    if ui.box.Text ~= code then return false end
    local clicked = fireButton(ui.btn)
    local focused = fireFocusLost(ui.box)
    return clicked or focused
end

fireButton = function(btn)
    if not btn or not btn.Parent then return false end
    local fired = false
    for _, signal in ipairs({ btn.MouseButton1Click, btn.Activated }) do
        local ok, list = pcall(getconnections, signal)
        if ok then
            for _, c in ipairs(list or {}) do
                if type(c.Fire) == "function" then
                    if pcall(c.Fire, c) then fired = true end
                end
            end
        end
        if typeof(firesignal) == "function" and pcall(firesignal, signal) then fired = true end
    end
    return fired
end

local pendingResult
local notificationCheck
local hookedNotifier
local function hookNotifier(notifier)
    if not notifier or hookedNotifier == notifier then return end
    local success, failure = notifier.Success, notifier.Error
    notifier.Success = function(self, message, ...)
        local cb = pendingResult
        local text = tostring(message):lower()
        -- the game calls this from its own thread, where task.spawn(cb) never runs;
        -- the Notification popup reader below settles pendingResult instead
        return success(self, message, ...)
    end
    notifier.Error = function(self, message, ...)
        local cb = pendingResult
        local text = tostring(message):lower()
        -- the game calls this from its own thread, where task.spawn(cb) never runs;
        -- the Notification popup reader below settles pendingResult instead
        return failure(self, message, ...)
    end
    hookedNotifier = notifier
    cleanups[#cleanups + 1] = function()
        notifier.Success, notifier.Error = success, failure
    end
end

;(function()
    local BAD = { "invalid", "incorrect", "wrong", "not found", "already", "expired", "sold out", "out of stock", "no longer" }
    local GOOD = { "redeemed", "success", "claimed", "spawned", "you got", "received" }
    local function check(label)
        local cb = pendingResult
        if not label then return end
        local real = typeof(label) == "Instance"
        if real and not label.Parent then return end
        local text = tostring(label.Text or ""):gsub("<[^>]->", "")
        local lower = text:lower()
        if lower == "" then return end
        local bad, good = false, false
        for _, w in ipairs(BAD) do if lower:find(w, 1, true) then bad = true break end end
        if not bad then
            for _, w in ipairs(GOOD) do if lower:find(w, 1, true) then good = true break end end
        end
        if not bad and not good then return end
        -- always show the toast so it's visible even when there's no pending redeem
        if good then
            -- check if it's a spawn notification or a redeem confirmation
            local spawnedName = text:match("^[Aa]n? (.+) has been spawned")
                or text:match("^[Aa]n? (.+) has spawned")
                or text:match("^(.+) has been spawned")
                or text:match("^(.+) has spawned")
                or text:match("^[Ss]pawned[!%s]+(.+)$")
                or text:match("^(.+) spawned")
            if spawnedName then
                spawnedName = spawnedName:gsub("[!%.%?]+$", ""):match("^%s*(.-)%s*$")
                toast("Spawned", spawnedName, false, "good")
            elseif lower:find("redeem", 1, true) or lower:find("success", 1, true) or lower:find("claimed", 1, true) or lower:find("you got", 1, true) or lower:find("received", 1, true) then
                toast("Redeemed", text, true, "good")
            else
                toast("Spawned", text, false, "good")
            end
        else
            toast("Failed", text, false, "warn")
        end
        if not cb then return end
        pendingResult = nil
        task.spawn(cb, good, text)
    end
    notificationCheck = check
    local function attachNotification(root)
        if not root then return end
        on(root.DescendantAdded, function(d)
            if d:IsA("TextLabel") then check(d) end
        end)
    end
    task.spawn(function()
        local pg = player:FindFirstChildOfClass("PlayerGui")
        local popup = pg and (pg:FindFirstChild("Notification") or pg:WaitForChild("Notification", 30))
        attachNotification(popup)
        local top = pg and (pg:FindFirstChild("TopNotification") or pg:WaitForChild("TopNotification", 30))
        local inner = top and (top:FindFirstChild("TopNotification") or top:WaitForChild("TopNotification", 30))
        local template = inner and (inner:FindFirstChild("Template") or inner:WaitForChild("Template", 30))
        attachNotification(template or top)
    end)
end)()

