local function typeIntoBox(code)
    code = cleanCode(code)
    local ui = resolveCodeUI()
    if not ui then log("Code box not found", "bad") return nil end
    pcall(function() ui.box.Text = code end)
    return ui.box.Parent and ui or nil
end

local parts, seen, lastPartAt, collecting, retypeListening, stopCollecting

local function copyFinalCode(code)
    task.defer(function()
        local copy = setclipboard or toclipboard or (syn and syn.write_clipboard)
        if type(copy) == "function" then pcall(copy, code) end
    end)
end

local lastRedeemAt = {}
local BUFFER_THROTTLE = 0.15

local function redeem(raw, preCleaned, onOutcome, _isRetry)
    -- Always normalize before any textbox or redeem action, including answers
    -- marked as pre-cleaned by the riddle and message-collection paths.
    local code = cleanCode(raw)
    if code == "" or #code > 50 or not code:match("^[A-Za-z0-9]+$") then
        if onOutcome then task.spawn(onOutcome, nil, "Malformed code") end
        return
    end
    local now = os.clock()
    if now < (lastRedeemAt[code] or 0) then return end
    local reported = false
    local function report(ok, message)
        if reported or not onOutcome then return end
        reported = true
        task.spawn(onOutcome, ok, message)
    end
    -- wire retypeInvalid BEFORE clearing pendingResult so we never have a nil gap
    -- popup reader fires cb = pendingResult; if we nil first and set after, the reader can fire into nil
    if settings.retypeInvalid then
        pendingResult = function(ok, message)
            if not ok and #parts < 5 then
                -- invalid — stay alive, next incoming word extends and retries
                collecting = true
                retypeListening = true
                lastPartAt = os.clock()
                log('<font color="#F87171">Invalid (' .. #parts .. ' word(s)) — waiting for word ' .. (#parts + 1) .. '…</font>', "bad", true)
            else
                -- success, or hit the 5-word cap — done
                retypeListening = false
                stopCollecting()
                report(ok, message)
            end
        end
    else
        -- not using retypeInvalid — clear any stale callback now
        pendingResult = nil
    end
    lastRedeemAt[code] = os.clock() + BUFFER_THROTTLE
    awaitingReward = os.clock() + 4  -- tightened from 6s: most games confirm within 3s
    if redeemRemote then
        if redeemRemoteIsFunction then
            task.spawn(function()
                pcall(function() redeemRemote:InvokeServer(code) end)
            end)
        else
            pcall(function() redeemRemote:FireServer(code) end)
        end
        copyFinalCode(code)
    else
        local submitOk, submitted = pcall(submitFast, code)
        if not submitOk or not submitted then
            pendingResult = nil
            log("Code UI submit failed", "bad")
            report(nil, "Code UI submit failed")
            return
        end
    end
    assistant.event("redeem", code)
    -- don't call report(true) here — let the notification popup reader settle it via pendingResult
    -- only call immediately if retypeInvalid is off (old behaviour, no outcome tracking needed)
    if not settings.retypeInvalid then
        report(true, code)
    end
end

