local shared = {}
function shared.enabled()
    return settings.sharedDbUrl ~= "" and httpRequest ~= nil
end
function shared.url(path)
    return (settings.sharedDbUrl:gsub("/+$", "")) .. path
end
function shared.voter()
    if settings.sharedVoter == "" then
        settings.sharedVoter = (HttpService:GenerateGUID(false):gsub("-", "")):lower()
        writeConfig()
    end
    return settings.sharedVoter
end
function shared.lookup(question, waitMs)
    local ok, res = pcall(httpRequest, {
        Url = shared.url("/v1/answer?q=" .. HttpService:UrlEncode(question) .. "&wait=" .. waitMs .. "&v=" .. shared.voter()),
        Method = "GET",
    })
    if not ok or type(res) ~= "table" then return nil end
    if tonumber(res.StatusCode or res.Status or res.status_code) ~= 200 then return nil end
    local decoded, data = pcall(function() return HttpService:JSONDecode(res.Body or res.body or "") end)
    if not decoded or type(data) ~= "table" or type(data.answer) ~= "string" then return nil end
    if #data.answer > 50 or not data.answer:match("^[A-Za-z0-9]+$") then return nil end
    return data.answer
end
local SHARED_OUTCOMES = { success = true, already_redeemed = true, sold_out = true, incorrect = true }
function shared.report(question, answer, outcome, source, ms)
    if not shared.enabled() or not SHARED_OUTCOMES[outcome] then return end
    task.spawn(function()
        pcall(httpRequest, {
            Url = shared.url("/v1/report"),
            Method = "POST",
            Headers = { ["Content-Type"] = "application/json" },
            Body = HttpService:JSONEncode({ q = question, answer = answer, outcome = outcome, voter = shared.voter(), source = source, ms = ms }),
        })
    end)
end
UI.shared = shared

