for _, source in ipairs({ CreatorSammyMemory, SammyClockKeys, CalciumSammyFacts, ImportedRiddlerDB }) do
        for k, v in pairs(source) do
            local phrase = tostring(k):lower()
            phrase = phrase:gsub("_", " "):gsub("[^%w%s]", " "):gsub("%s+", " ")
            phrase = phrase:match("^%s*(.-)%s*$")
            if phrase and phrase ~= "" and not memoryLookup[phrase] then
                memoryLookup[phrase] = tostring(v)
                table.insert(memoryPhrases, phrase)
            end
        end
    end
    table.sort(memoryPhrases, function(a, b) return #a > #b end)
end

local STOP_WORDS = {
    ["the"]=true, ["is"]=true, ["are"]=true, ["was"]=true, ["a"]=true, ["an"]=true,
    ["of"]=true, ["to"]=true, ["in"]=true, ["it"]=true, ["s"]=true,
    ["what"]=true, ["whats"]=true, ["which"]=true, ["who"]=true, ["tell"]=true,
    ["me"]=true, ["please"]=true, ["pls"]=true, ["code"]=true, ["answer"]=true,
    ["riddle"]=true, ["question"]=true, ["clue"]=true, ["hint"]=true,
    ["cual"]=true, ["es"]=true, ["el"]=true, ["la"]=true, ["de"]=true,
    ["que"]=true, ["dime"]=true, ["mi"]=true, ["my"]=true,
    ["sammy"]=true, ["sammys"]=true, ["his"]=true, ["her"]=true
}

-- Sammy uses US Central time. DST runs from the second Sunday in March to
-- the first Sunday in November; this keeps time/day/date correct year-round.
local function sammyNthSunday(year, month, nth)
    local first = DateTime.fromUniversalTime(year, month, 1, 12, 0, 0).UnixTimestamp
    local weekday = os.date("!*t", first).wday
    return 1 + ((1 - weekday + 7) % 7) + (nth - 1) * 7
end
local function sammyClock()
    local now = os.time()
    local utc = os.date("!*t", now)
    local startDay = sammyNthSunday(utc.year, 3, 2)
    local endDay = sammyNthSunday(utc.year, 11, 1)
    local dstStart = DateTime.fromUniversalTime(utc.year, 3, startDay, 8, 0, 0).UnixTimestamp
    local dstEnd = DateTime.fromUniversalTime(utc.year, 11, endDay, 7, 0, 0).UnixTimestamp
    local isDst = now >= dstStart and now < dstEnd
    return os.date("!*t", now + ((isDst and -5 or -6) * 3600)), isDst
end
local function dynamicSammyAnswer(request)
local q = tostring(request or ""):lower():gsub("[^%w%s]", " "):gsub("%s+", " ")
    local clock, isDst = sammyClock()
    local days = { "Sunday", "Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday" }
    local months = { "January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December" }
    if q:find("time", 1, true) or q:find("heure", 1, true) or q:find("hora", 1, true) then
        local hour = clock.hour % 12
        if hour == 0 then hour = 12 end
        return string.format("%d:%02d %s CT", hour, clock.min, clock.hour >= 12 and "PM" or "AM")
    end
    if q:find("day", 1, true) or q:find("jour", 1, true) or q:find("dia", 1, true) then return days[clock.wday] end
    if q:find("date", 1, true) or q:find("today", 1, true) or q:find("aujourd", 1, true) or q:find("fecha", 1, true) then
        return string.format("%s %d, %d", months[clock.month], clock.day, clock.year)
    end
    if q:find("zone", 1, true) then return isDst and "CDT" or "CST" end
    return string.format("%02d%02d", clock.hour, clock.min)
end

local function isSammyClockQuestion(request)
    local q = tostring(request or ""):lower():gsub("[^%w%s]", " ")
    return q:find("time", 1, true) or q:find("heure", 1, true) or q:find("hora", 1, true)
        or q:find("day", 1, true) or q:find("jour", 1, true) or q:find("dia", 1, true)
        or q:find("date", 1, true) or q:find("today", 1, true) or q:find("aujourd", 1, true)
end

-- Token index makes broad question matching inspect a small candidate set,
-- rather than walking every one of the 13k+ imported riddles per message.
local memoryTokenIndex = {}
for _, phrase in ipairs(memoryPhrases) do
    local seen = {}
    for word in phrase:gmatch("%w+") do
        if not STOP_WORDS[word] and not seen[word] then
            seen[word] = true
            memoryTokenIndex[word] = memoryTokenIndex[word] or {}
            table.insert(memoryTokenIndex[word], phrase)
        end
    end
end
local function indexedCandidates(part)
    local best, bestSize, seen = nil, math.huge, {}
    for word in part:gmatch("%w+") do
        if not STOP_WORDS[word] and not seen[word] then
            seen[word] = true
            local bucket = memoryTokenIndex[word]
            if bucket and #bucket < bestSize then best, bestSize = bucket, #bucket end
        end
    end
    return best or {}
end
local function normalizeRequestText(s)
    s = tostring(s or ""):lower()
    s = s:gsub("[^%w%s%+&,]", " ")
    s = s:gsub("%s+", " ")
    return (s:match("^%s*(.-)%s*$"))
end

local function splitRequestParts(text)
    local norm = normalizeRequestText(text)
    if norm == "" then return {} end
    norm = norm:gsub("%+", " | "):gsub(",", " | "):gsub("&", " | ")
    norm = " " .. norm .. " "
    norm = norm:gsub(" and ", " | "):gsub(" plus ", " | "):gsub(" then ", " | ")
    norm = norm:gsub(" y ", " | "):gsub(" mas ", " | ")

    local parts = {}
    for piece in norm:gmatch("[^|]+") do
        piece = piece:gsub("%s+", " "):match("^%s*(.-)%s*$")
        if piece ~= "" then table.insert(parts, piece) end
    end
    return parts
end

local function findMemoryValue(part)
    if isSammyClockQuestion(part) then return dynamicSammyAnswer(part), "sammy clock" end
    local exact = memoryLookup[part]
    if exact then
        return exact == "DYNAMIC" and dynamicSammyAnswer(part) or exact, part
    end
    local padded = " " .. part .. " "
    local candidates = indexedCandidates(part)
    for _, phrase in ipairs(candidates) do
        if padded:find(" " .. phrase .. " ", 1, true) then
            local value = memoryLookup[phrase]
            return value == "DYNAMIC" and dynamicSammyAnswer(part) or value, phrase
        end
    end
    local bestPhrase, bestWords = nil, 0
    for _, phrase in ipairs(candidates) do
        local total, matched = 0, 0
        for word in phrase:gmatch("%w+") do
            total += 1
            if padded:find(" " .. word .. " ", 1, true) then matched += 1 end
        end
        if total >= 2 and matched == total and total > bestWords then bestPhrase, bestWords = phrase, total end
    end
    if bestPhrase then
        local value = memoryLookup[bestPhrase]
        return value == "DYNAMIC" and dynamicSammyAnswer(part) or value, bestPhrase
    end
    return nil, nil
end

local function hasMeaningfulWord(str)
    for w in tostring(str):gmatch("[%w]+") do
        if not STOP_WORDS[w] then return true end
    end
    return false
end

local function analyzeRequest(text)
    local result = { facts = {}, unresolved = {}, complete = false, code = "" }
    local parts = splitRequestParts(text)
    if #parts == 0 then return result end

    local pieces = {}
    for _, part in ipairs(parts) do
        local value, phrase = findMemoryValue(part)
        if value then
            table.insert(pieces, tostring(value))
            table.insert(result.facts, string.format('%s = %s', phrase, tostring(value):upper()))

            local padded  = " " .. part .. " "
            local target  = " " .. phrase .. " "
            local idx     = padded:find(target, 1, true)
            local leftover = idx and (padded:sub(1, idx) .. padded:sub(idx + #target)) or padded
            if hasMeaningfulWord(leftover) then
                table.insert(result.unresolved, part)
            end
        elseif hasMeaningfulWord(part) then

            table.insert(result.unresolved, part)
        end
    end

    if #pieces > 0 then
        result.code = (table.concat(pieces, ""):upper():gsub("%s+", ""))
    end
    result.complete = (#result.unresolved == 0 and #pieces > 0)
    return result
end

HexLocal.analyze = analyzeRequest
HexLocal.animal = checkLocalAnimalCompletion
function HexLocal.relevant(question, maxItems)
    local msg = " " .. tostring(question or ""):lower():gsub("[^%w%s]", " "):gsub("%s+", " ") .. " "
    local hits = {}
    local relevantCandidates = indexedCandidates(msg)
    for _, phrase in ipairs(relevantCandidates) do
        local words, all = 0, true
        for w in phrase:gmatch("[%w]+") do
            words += 1
            if not msg:find(" " .. w .. " ", 1, true) then all = false break end
        end
        if all and words > 0 then hits[#hits + 1] = { phrase = phrase, words = words } end
    end
    table.sort(hits, function(a, b) return a.words > b.words end)
    local lines, seen = {}, {}
    for _, h in ipairs(hits) do
        local line = h.phrase .. " = " .. tostring(memoryLookup[h.phrase]):upper()
        if not seen[line] then
            seen[line] = true
            lines[#lines + 1] = line
            if #lines >= (maxItems or 25) then break end
        end
    end
    return lines
end
end)()

solveRiddle = function(question)
    question = trim(question)
    if RS.questionLine then
        RS.questionLine.finish(esc("Question: " .. question))
        RS.questionLine = nil
    end
    if question == "" then return end
    local storedAnswers = RiddleStore.get(question)
    if type(storedAnswers) == "table" and #storedAnswers > 0 then
        task.spawn(function()
            for i, answer in ipairs(storedAnswers) do
                redeem(answer, true)
                if i < #storedAnswers then task.wait(tonumber(settings.multiDelay) or 0.35) end
            end
        end)
        return
    end
    local hexStart = os.clock()
    local function hexReport(code)
        return function(ok, message)
            local outcome = RiddleEngine.classifyFeedback(ok, tostring(message or ""))
            shared.report(question, cleanCode(code), outcome, "local", math.floor((os.clock() - hexStart) * 1000))
        end
    end
    local hexOk, hexA = pcall(UI.HexLocal.analyze, question)
    local _, hexAnimal = pcall(UI.HexLocal.animal, question)
    if hexOk and type(hexA) == "table" then
        if hexA.complete and hexA.code ~= "" then
            log("Local Full Match (" .. #hexA.facts .. " fact(s)) -> Code: " .. hexA.code, "good")
            redeem(hexA.code, false, hexReport(hexA.code))
            return
        end
        if type(hexAnimal) == "string" and #hexA.unresolved == 0 then
            log("Local Match Solved -> Code: " .. hexAnimal, "good")
            redeem(hexAnimal, false, hexReport(hexAnimal))
            return
        end
        if #hexA.facts > 0 then
            log("Mixed request: " .. #hexA.facts .. " local fact(s) + " .. #hexA.unresolved .. " part(s) for the AI...", "sys")
        end
    end
    if not settings.riddleSolver then
        if hexOk and type(hexA) == "table" and hexA.code ~= "" then
            log("AI disabled. Using local data only -> Code: " .. hexA.code, "sys")
            redeem(hexA.code, false, hexReport(hexA.code))
            return
        end
        log("Riddle seen, solver is off", "sys")
        return
    end
    if not httpRequest then
        log("Executor has no HTTP request", "bad")
        return
    end
    local key = RiddleEngine.norm(question)
    local cached = RiddleEngine.cacheLookup(riddleStore, question, os.time())
    local useShared = shared.enabled() and not cached
    if UI.AI.key() == "" and not cached and not useShared then
        log(UI.AI.active().name .. " API key needed", "bad")
        warnNoKey()
        return
    end
    if activeSolves[key] or (solving[key] and os.clock() - solving[key] < SOLVE_COOLDOWN) then return end
    solving[key] = os.clock()
    activeSolves[key] = true

    local started = os.clock()
    if not cached then log("AI: Sending riddle to " .. UI.AI.active().name .. " (" .. tostring(UI.AI.active().model) .. ")...", "ai") end
    local solvingLine = liveLine(cached and "Known riddle, submitting" or "AI is solving")
    assistant.event("thinking")
    task.spawn(function()
        local state = { sharedDone = not useShared, aiDone = false, tried = {} }
        if useShared then
            task.spawn(function()
                state.shared = shared.lookup(question, 15000)
                state.sharedDone = true
            end)
        end
        task.spawn(function()
            state.solveOk, state.r = pcall(RiddleEngine.solve, riddleDeps, question)
            state.aiDone = true
        end)

        local function aiAnswer()
            local r = state.r
            if not state.solveOk or type(r) ~= "table" or not r.answer or r.answer == "" then return nil end
            if r.source ~= "cache" and not r.ok then return nil end
            return r.answer
        end
        local function nextCandidate()
            local deadline = os.clock() + 32
            while os.clock() < deadline and gui.Parent do
                if state.shared and not state.tried[state.shared] then
                    return state.shared, { source = "shared", model = "none", ms = (os.clock() - started) * 1000, calls = 0 }
                end
                local answer = aiAnswer()
                if answer and not state.tried[answer] then return answer, state.r end
                if state.aiDone and state.sharedDone then return nil end
                task.wait()
            end
            return nil
        end

        local attempt
        attempt = function()
            local answer, meta = nextCandidate()
            if not gui.Parent or not settings.riddleSolver then
                activeSolves[key] = nil
                solving[key] = nil
                return
            end
            if not answer then
                activeSolves[key] = nil
                solving[key] = nil
                local r = state.r
                local reason
                if not state.solveOk then
                    reason = "Solver error: " .. tostring(r)
                elseif type(r) == "table" and r.answer and r.answer ~= "" and not r.ok then
                    reason = "AI answer rejected (" .. tostring(r.reason) .. "): " .. r.answer
                else
                    reason = "AI failed: " .. tostring(type(r) == "table" and r.reason or "no answer")
                end
                solvingLine.finish(esc(reason), "#F87171")
                log(("AI (%.2fs): %s"):format(os.clock() - started, reason), "bad")
                assistant.event("stumped")
                if type(r) == "table" and next(state.tried) == nil then
                    r.source = r.source or "gemini"
                    riddleStore = RiddleEngine.record(riddleStore, question, r.answer or "", r.answer and "withheld" or "unknown", r, os.time())
                    riddleDeps.store = riddleStore
                    saveRiddleStore()
                end
                return
            end
            state.tried[answer] = true
            local chosenMs = math.floor((os.clock() - started) * 1000)
            local source = meta.source == "shared" and "shared" or meta.source == "cache" and "cache" or meta.source == "knowledge" and "knowledge" or "gemini"
            local label = meta.source == "shared" and "Shared answer"
                or meta.source == "cache" and "Previously accepted candidate"
                or meta.source == "knowledge" and "Knowledge candidate"
                or "AI candidate"
            solvingLine.finish(("%s in %.2fs · <font face=\"RobotoMono\">%s</font>"):format(label, os.clock() - started, esc(answer)), "#FFD700")
            assistant.event("answer", answer)
            log(("AI Solved Riddle in %.2fs -> Code: %s"):format(os.clock() - started, answer), "good")
            redeem(answer, true, function(ok, message)
                local outcome = RiddleEngine.classifyFeedback(ok, tostring(message or ""))
                if outcome == "success" then
                    RiddleStore.add(question, { answer }, true)
                    saveRiddleStore()
                end
                riddleStore = RiddleEngine.record(riddleStore, question, answer, outcome, meta, os.time())
                riddleDeps.store = riddleStore
                saveRiddleStore()
                shared.report(question, answer, outcome, source, chosenMs)
                if outcome ~= "success" and outcome ~= "timeout" then
                    log(OUTCOME_TEXT[outcome] or outcome, outcome == "incorrect" and "bad" or "sys")
                end
                if outcome == "incorrect" then
                    solvingLine = liveLine("Trying the other answer")
                    attempt()
                    return
                end
                activeSolves[key] = nil
                if outcome ~= "success" then solving[key] = nil end
            end)
        end
        attempt()
    end)
end
end

local function isRiddleTrigger(word)
    return RIDDLE_TRIGGERS[word] or word:find("riddle", 1, true) ~= nil or word:find("question", 1, true) ~= nil
end

local function findWord(hay, needle)
    local init = 1
    while true do
        local s, e = hay:find(needle, init, true)
        if not s then return nil end
        local before = s == 1 or hay:sub(s - 1, s - 1) == " "
        local nextCh = hay:sub(e + 1, e + 1)
        local after = nextCh == "" or nextCh == " " or nextCh == ":" or needle:sub(-1) == ":"
        if before and after then return s, e end
        init = s + 1
    end
end

local function matchTrigger(text)
    local loose, map = looseText(text)
    local best, bestS, bestE
    for _, word in ipairs(sortedTriggers) do
        local s, e = findWord(loose, word)
        if s and (not bestS or s < bestS or (s == bestS and e > bestE)) then
            best, bestS, bestE = word, s, e
        end
    end
    if not best then return nil end
    local rest = text:sub(map[bestE] + 1):gsub("…", "...")
    if isRiddleTrigger(best) then
        rest = trim(rest):gsub("^:%s*", "")
    else
        rest = rest:gsub("^[^%w\"'%(]+", "")
        rest = rest:gsub("[%s%.!%?,]+$", "")
    end
    return best, rest
end

local awaitingQuestion = 0
local QUESTION_TIMEOUT = 60
local QUESTION_JOIN = 1.5
local QUESTION_END_JOIN = 0.3

local function captureQuestion(text: string)
    local now = os.clock()
    local afterTrigger = RS.capture ~= nil and #RS.capture.parts == 0
    local state = RS.capture or RiddleEngine.newCapture(now)
    local nextState, _, captureError = RiddleEngine.capture(state,text,now,afterTrigger)
    if captureError then
        RS.token += 1
        RS.capture = nil
        awaitingQuestion = 0
        if RS.questionLine then
            RS.questionLine.finish(esc(captureError),"#F87171")
            RS.questionLine = nil
        end
        log(captureError,"bad")
        return
    end
    if nextState == state then return end
    RS.capture = nextState
    awaitingQuestion = nextState.deadline
    RS.token += 1
    local token = RS.token
    if not RS.questionLine then RS.questionLine = liveLine("Collecting full question") end
    local wait = text:find("%?%s*$") and QUESTION_END_JOIN or QUESTION_JOIN
    task.delay(wait,function()
        if token ~= RS.token or not gui.Parent then return end
        awaitingQuestion = 0
        RS.capture = nil
        solveRiddle(table.concat(nextState.parts," "))
    end)
end

parts, seen, lastPartAt = {}, {}, 0
collecting = false
local partLines = {}
local PART_TIMEOUT = 20
retypeListening = false  -- true when we're waiting for the corrected word after an invalid

local function startCollecting()
    collecting, parts, partLines, lastPartAt = true, {}, {}, os.clock()
    retypeListening = false
    seen = {}
end
stopCollecting = function()
    collecting, parts, partLines = false, {}, {}
    retypeListening = false
    seen = {}
end

function UI.cancelTracking()
    if collecting or retypeListening then
        stopCollecting()
        pendingResult = nil
        log("Code tracking cancelled", "sys")
        toast("Cancelled", "Code tracking stopped", false, "sys")
    end
end

local function renderParts()
    local total = settings.submitAfter
    for i, p in ipairs(parts) do
        local line = '<font face="RobotoMono">' .. esc(p) .. "</font>"
            .. "  <font color=\"#8E8E96\">" .. i .. "/" .. total .. "</font>"
        if partLines[i] and partLines[i].Parent then
            partLines[i].Text = line
        else
            partLines[i] = log(line, "info", true)
        end
    end
end

local function capturePart(part)
    if part == "" then return end

    -- retypeListening: last redeem was invalid, extend the code with this new word and retry
    if retypeListening then
        retypeListening = false
        seen[part] = nil  -- bypass dedup — owner may repeat a word
        seen[part] = true
        lastPartAt = os.clock()
        parts[#parts + 1] = part
        local combined = table.concat(parts)
        log('<font color="#FFD700">Retype attempt (' .. #parts .. '/5) → ' .. esc(combined) .. '</font>', "sys", true)
        redeem(combined, true)
        return
    end

    if seen[part] then return end
    if os.clock() - lastPartAt > PART_TIMEOUT then
        log("Code parts timed out", "sys")
        stopCollecting()
        return
    end
    seen[part] = true
    lastPartAt = os.clock()
    parts[#parts + 1] = part

    -- twoWordCheck: at 2 parts, attempt an early redeem and keep listening regardless
    -- collection continues until submitAfter parts arrive OR user cancels
    if settings.twoWordCheck and #parts == 2 and settings.submitAfter > 2 then
        local combined = table.concat(parts)
        redeem(combined, true)
        renderParts()
        return  -- keep listening — do NOT stopCollecting
    end

    -- last part: redeem. If retypeInvalid is on, keep collecting so next word
    -- can extend the code on invalid. Otherwise stop immediately.
    if #parts >= settings.submitAfter then
        local combined = table.concat(parts)
        if not settings.retypeInvalid then
            stopCollecting()
        end
        log("Redeemed " .. combined, "good")
        toast("Redeemed", combined, true, "good")
        redeem(combined, true)
        return
    end
    log("Detected (Start): " .. part, "sys")
    log("Progress: [" .. table.concat(parts) .. "] (Remaining: " .. (settings.submitAfter - #parts) .. ")", "sys")
    renderParts()
end

local seenTTL = {}
local function once(key)
    local now = os.clock()
    local last = seenTTL[key]
    if last and now - last < 1.25 then return false end
    seenTTL[key] = now
    return true
end

local function extractDirectCode(text)
    local token = tostring(text or ""):match("[Tt]he%s+code%s+is%s+([%w%p]+)")
        or tostring(text or ""):match("[Cc]ode%s+is%s+([%w%p]+)")
        or tostring(text or ""):match("[Uu]se%s+the%s+code%s+([%w%p]+)")
    if not token then return nil end
    token = token:gsub("^[^%w]+", ""):gsub("[^%w]+$", "")
    if token == "" then return nil end
    return cleanCode(token):upper()
end

local function onAnnouncement(message)
    if not message or message == "" then return end

    if type(message) ~= "string" then error("Announcement must be text, got " .. type(message)) end
    local text = trim(RiddleEngine.decodeAnnouncement(message))
    if text == "" then return end

    local directCode = extractDirectCode(text)
    if directCode and once("code:" .. directCode) then
        redeem(directCode, true)
        return
    end

    local lower = text:lower()

    -- only match announcements that are literally "Spawned <Name>" — e.g. "Spawned Skibidi Toilet"
    local spawnedName = text:match("^[Ss]pawned%s+(.+)$")
    if spawnedName then
        spawnedName = spawnedName:gsub("[!%.%?]+$", ""):match("^%s*(.-)%s*$")
        local nameTag = '<font color="#4ADE80"><b>' .. esc(spawnedName) .. '</b></font>'
        log('<font color="#4ADE80">Spawned: ' .. nameTag .. '</font>', "good", true)
        toast("Spawned", spawnedName, false, "good")
        if os.clock() < awaitingReward then
            awaitingReward = 0
            assistant.event("reward", text)
        end
        return
    end

    if os.clock() < awaitingQuestion and not matchTrigger(text) then
        captureQuestion(text)
        return
    end

    local trigger, rest = matchTrigger(text)
    if trigger then
        stopCollecting()
        awaitingQuestion = 0
        RS.buffer = {}
        RS.capture = nil
        RS.token += 1
        if not isRiddleTrigger(trigger) and rest ~= "" and not rest:find("%s") then
            redeem(rest)
            log("Trigger \xe2\x86\x92 " .. rest, "sys")
        elseif isRiddleTrigger(trigger) then
            log("Riddle detected! Trigger ('" .. text .. "')", "sys")
            awaitingQuestion = os.clock() + QUESTION_TIMEOUT
            RS.capture = RiddleEngine.newCapture(os.clock())
            if RS.questionLine then RS.questionLine.finish("Question skipped") end
            local line = liveLine("Collecting full question")
            RS.questionLine = line
            if rest ~= "" then captureQuestion(rest) end
            local token = RS.token
            task.delay(QUESTION_TIMEOUT,function()
                if RS.questionLine == line and token == RS.token then
                    line.finish("No complete question received","#F87171")
                    RS.questionLine = nil
                    RS.capture = nil
                    awaitingQuestion = 0
                end
            end)
        else
            log("Trigger detected ('" .. text .. "'). Starting capture (" .. settings.submitAfter .. " messages)...", "sys")
            log('<font color="#FFD700">Code redeemer started tracking</font>', "sys", true)
            assistant.event("tracking")
            startCollecting()
        end
        if not settings.armed then UI.setArmed(true, true) end
        return
    end

    if lower:find("riddle", 1, true) then
        log("No trigger matched: " .. text, "sys")
    end
    if not settings.armed then return end

    if settings.riddleSolver and not collecting and RiddleEngine.looksLikeQuestion(text) then
        captureQuestion(text)
        return
    end
    if not collecting then return end

    if text:find("%s") then
        -- only attempt to split a multi-word message when twoWordCheck is enabled
        if settings.twoWordCheck then
            local combined = text:match("^([%w_]+%s+[%w_]+)$") or text:match("^([%w_]+%s+[%w_]+%s+[%w_]+%s+[%w_]+)$")
            if combined then
                capturePart((combined:gsub("%s+", "")))
            end
        end
        return
    end
    capturePart(cleanCode(text))
end
UI.simulate = onAnnouncement

task.spawn(function()
    local remote
    pcall(function()
        local net = ReplicatedStorage:WaitForChild("Packages", 10):WaitForChild("Net", 10)
        for _, d in ipairs(net:GetDescendants()) do
            if remote then break end
            if d:IsA("RemoteEvent") then
                local ok, list = pcall(getconnections, d.OnClientEvent)
                for _, c in ipairs(ok and list or {}) do
                    local fn = c.Function
                    if type(fn) == "function" and debugSource(fn):find("NotificationController", 1, true) then
                        remote = d
                        break
                    end
                end
            end
        end
    end)
    if not gui.Parent then return end
    if not remote then
        log("Announcement feed not found", "bad")
        return
    end
    UI.feedRemote = remote
    on(remote.OnClientEvent, function(message)
        local body = type(message) == "table" and (message.Text or message.Message or message.Body or message[1]) or message
        if notificationCheck then notificationCheck({ Text = body, Parent = true }) end
        -- drop echo from FakeAnc (it already called simulate directly)
        if UI._fakeAncEcho and UI._fakeAncEcho == tostring(message or ""):gsub("^%s+",""):gsub("%s+$","") then
            UI._fakeAncEcho = nil
            return
        end
        local ok, err = pcall(onAnnouncement, message)
        if not ok then log("Error: " .. tostring(err), "bad") end
    end)
    -- pre-warm codeUI cache — retry until Codes GUI is present (up to 10s)
    task.spawn(function()
        local deadline = os.clock() + 10
        local preUI
        repeat
            preUI = resolveCodeUI()
            if not preUI then task.wait(0.1) end
        until preUI or os.clock() > deadline
        if preUI then
            hookNotifier(preUI.notifier)
            log("Code UI cached, notifier hooked", "sys")
        else
            log("Code UI not found at startup — will resolve on first redeem", "sys")
        end
    end)

    pcall(function()
        local net = ReplicatedStorage:WaitForChild("Packages", 5):WaitForChild("Net", 5)
        local candidates = {
            { "MerchShop",          "RedeemCode"  },
            { "ModdedStockService", "Redeem"      },
            { "StockEventService",  "Redeem"      },
        }
        for _, pair in ipairs(candidates) do
            local service = net:FindFirstChild(pair[1])
            if service then
                local obj = service:FindFirstChild(pair[2])
                if obj and (obj:IsA("RemoteEvent") or obj:IsA("RemoteFunction")) then
                    redeemRemote = obj
                    redeemRemoteIsFunction = obj:IsA("RemoteFunction")
                    log("Direct remote: " .. pair[1] .. "/" .. pair[2], "sys")
                    break
                end
            end
        end
    end)

    log("Listening for announcements", "sys")
end)

end)()

function UI.destroy()
    if savePending then writeConfig() end
