-- ============================================================
-- SECTION 3: CENTRAL TIME SYSTEM (from riddler_v29)
-- ============================================================
if not _G.__RiddlerCT then
    _G.__RiddlerCentralOffset = -6  -- CST base
    _G.__RiddlerCT = function(epoch)
        epoch = epoch or os.time()
        -- DST: second Sunday March → first Sunday November
        local function nthSunday(y, m, n)
            local t = os.time({ year=y, month=m, day=1, hour=2, min=0, sec=0 })
            local wd = tonumber(os.date("!%w", t))
            local first = (wd == 0) and 1 or (8 - wd)
            return os.time({ year=y, month=m, day=first + (n-1)*7, hour=2, min=0, sec=0 })
        end
        local y = tonumber(os.date("!%Y", epoch))
        local dstStart = nthSunday(y, 3, 2)   -- 2nd Sunday March
        local dstEnd   = nthSunday(y, 11, 1)  -- 1st Sunday November
        local offset = (epoch >= dstStart and epoch < dstEnd) and -5 or -6
        local adj = epoch + offset * 3600
        local t = os.date("!*t", adj)
        t.offset = offset
        return t
    end
    _G.__RiddlerPin = { year=2026, month=11, day=2 }
    _G.__RiddlerNow = function()
        local real = os.time()
        local ct = _G.__RiddlerCT(real)
        local pin = _G.__RiddlerPin
        if not pin then return real end
        local pinEpoch = os.time({ year=pin.year, month=pin.month, day=pin.day, hour=0, min=0, sec=0 })
        if real < pinEpoch then return pinEpoch end
        return real
    end
end

