                Position = UDim2.new(0, 0, 1, -4),
                Size = UDim2.new(1, 0, 0, 4),
                BackgroundColor3 = C.Faint,
                Name = "TimerBg",
            })
            local timerBar = safeNew("Frame", {
                Parent = timerBg,
                Size = UDim2.new(1, 0, 1, 0),
                BackgroundColor3 = C.Green,
                Name = "TimerFill",
            })
            safeNew("UICorner", { Parent = timerBg, CornerRadius = UDim.new(0, 2) })
            safeNew("UICorner", { Parent = timerBar, CornerRadius = UDim.new(0, 2) })

            ogCards[uid] = card

            -- countdown tween
            local tw = TS:Create(timerBar,
                TweenInfo.new(CARD_LIFETIME, Enum.EasingStyle.Linear),
                { Size = UDim2.new(0, 0, 1, 0) }
            )
            tw:Play()
            task.delay(CARD_LIFETIME, function()
                if ogCards[uid] == card then
                    ogCards[uid] = nil
                    pcall(function() card:Destroy() end)
                end
            end)
        end

        -- ---- liveboard hooks ----
        function startOGListening()
            stopOGListening()
            ogListening = true
            local net = RS:FindFirstChild("Packages")
            net = net and net:FindFirstChild("Net")
            if not net then
                -- try direct RE folder
                net = RS:FindFirstChild("RE") or RS
            end

            local newEntryRE = net:FindFirstChild("NewEntry")
                or RS:FindFirstChild("NewEntry")
            local claimRE    = net:FindFirstChild("ClaimEntry")
                or RS:FindFirstChild("ClaimEntry")

            -- Use getconnections or just hook with direct RE path
            if newEntryRE then
                ogConn1 = newEntryRE.OnClientEvent:Connect(function(uid, mutation, ownerName, isLocal)
                    -- uid is the animal's display name in some builds
                    local name = tostring(uid)
                    local mut  = detectMutation(uid, mutation)
                    task.spawn(function()
                        playAlert()
                        makeCard(tostring(uid), name, mut, ownerName)
                        if ogAutoTrade then
                            task.wait(0.3)
                            pcall(function()
                                local target = Players:FindFirstChild(tostring(ownerName or ""))
                                if target then sendTradeInvite(target) end
                            end)
                        end
                        if ogAutoDuel then
                            task.wait(0.3)
                            pcall(function()
                                local target = Players:FindFirstChild(tostring(ownerName or ""))
                                if target then sendDuelInvite(target) end
                            end)
                        end
                    end)
                end)
            end

            if claimRE then
                ogConn2 = claimRE.OnClientEvent:Connect(function(uid, claimOwner)
                    -- remove card when claimed
                    local card = ogCards[tostring(uid)]
                    if card then
                        ogCards[tostring(uid)] = nil
                        pcall(function()
                            TS:Create(card, TweenInfo.new(0.25, Enum.EasingStyle.Quad), { BackgroundTransparency = 1 }):Play()
                            task.delay(0.3, function() pcall(function() card:Destroy() end) end)
                        end)
                    end
                end)
            end
        end

        function stopOGListening()
            ogListening = false
            if ogConn1 then pcall(function() ogConn1:Disconnect() end); ogConn1 = nil end
            if ogConn2 then pcall(function() ogConn2:Disconnect() end); ogConn2 = nil end
        end

        -- Manual sweep: scan RS for any existing liveboard entries
        function manualOGSweep()
            pcall(function()
                local lb = RS:FindFirstChild("Liveboard") or RS.Packages:FindFirstChild("Liveboard")
                if not lb then return end
                local t = require(lb)
                if type(t) ~= "table" then return end
                for uid, entry in pairs(t) do
                    if type(entry) == "table" then
                        local name = entry.Name or entry.DisplayName or tostring(uid)
                        local mut  = detectMutation(uid, entry.Mutation)
                        local owner= entry.OwnerName or entry.Owner or "?"
                        makeCard(tostring(uid), name, mut, owner)
                    end
                end
            end)
        end

        -- Auto-start listening
        startOGListening()
    end

    -- Register page builder to run once base UI is live
    local function tryBuildOG()
        if _G.__SkibidiPage then
            buildOGTab()
        else
            task.delay(2, tryBuildOG)
        end
    end
    task.spawn(tryBuildOG)
end

-- ============================================================
-- SECTION 5: FX ADMIN TAB
-- Anchor(F), InstantBuy(H), AutoBuy(G) keybinds
-- ProximityPrompt scanner, nearest-target panel
-- NO BACKDOOR — cleaned port from Fx_Admin_Abuse_Helper.txt
-- ============================================================
do
    local UIS  = game:GetService("UserInputService")
    local WS   = game:GetService("Workspace")
    local RunS = game:GetService("RunService")

    local FX = {
        AnchorKey    = Enum.KeyCode.F,
        InstantBuyKey= Enum.KeyCode.H,
        AutoBuyKey   = Enum.KeyCode.G,
        Anchor       = false,
        InstantBuy   = false,
        AutoBuy      = false,
    }

    local fxConn_anchor, fxConn_ibuy, fxConn_abuy

    -- ---- ProximityPrompt helpers (from Fx_Admin_Abuse_Helper) ----
    local function GetPromptModel(prompt)
        if not prompt then return nil end
        local att = prompt.Parent
        if not att then return nil end
        local part = att:IsA("BasePart") and att or att.Parent
        if not part then return nil end
        local model = part:FindFirstAncestorOfClass("Model") or part
        return model
    end

    local function GetPromptPosition(prompt)
        local model = GetPromptModel(prompt)
        if not model then return nil end
        if model.PrimaryPart then return model.PrimaryPart.Position end
        local ok, cf = pcall(function() return model:GetBoundingBox() end)
        if ok then return cf.Position end
        return nil
    end

    -- ---- Anchor toggle ----
    local function StartAnchor()
        StopAnchor()
        fxConn_anchor = RunS.Heartbeat:Connect(function()
            if not FX.Anchor then return end
            pcall(function()
                local lp = game:GetService("Players").LocalPlayer
                local char = lp and lp.Character
                if not char then return end
                for _, part in ipairs(char:GetDescendants()) do
                    if part:IsA("BasePart") then
                        part.Anchored = true
                    end
                end
            end)
        end)
    end

    function StopAnchor()
        if fxConn_anchor then
            pcall(function() fxConn_anchor:Disconnect() end)
            fxConn_anchor = nil
        end
        -- un-anchor character
        pcall(function()
            local lp = game:GetService("Players").LocalPlayer
            local char = lp and lp.Character
            if char then
                for _, part in ipairs(char:GetDescendants()) do
                    if part:IsA("BasePart") then
                        part.Anchored = false
                    end
                end
            end
        end)
    end

    -- ---- InstantBuy toggle ----
    local function StartInstantBuy()
        StopInstantBuy()
        fxConn_ibuy = RunS.Heartbeat:Connect(function()
            if not FX.InstantBuy then return end
            pcall(function()
                for _, pp in ipairs(WS:GetDescendants()) do
                    if pp:IsA("ProximityPrompt") then
                        pp.HoldDuration = 0
                        pp.MaxActivationDistance = 20
                    end
                end
            end)
        end)
    end

    function StopInstantBuy()
        if fxConn_ibuy then
            pcall(function() fxConn_ibuy:Disconnect() end)
            fxConn_ibuy = nil
        end
    end

    -- ---- AutoBuy ----
    local autoBuyActive = false
    local autoBuyConn

    local function StartAutoBuy()
        StopAutoBuy()
        autoBuyActive = true
        autoBuyConn = RunS.RenderStepped:Connect(function()
            if not FX.AutoBuy then return end
            pcall(function()
                local lp = game:GetService("Players").LocalPlayer
                local char = lp and lp.Character
                local root = char and char:FindFirstChild("HumanoidRootPart")
                if not root then return end
                for _, pp in ipairs(WS:GetDescendants()) do
                    if pp:IsA("ProximityPrompt") then
                        local pos = GetPromptPosition(pp)
                        if pos and (root.Position - pos).Magnitude < 15 then
                            pcall(fireproximityprompt, pp)
                        end
                    end
                end
            end)
        end)
    end

    function StopAutoBuy()
        autoBuyActive = false
        if autoBuyConn then
            pcall(function() autoBuyConn:Disconnect() end)
            autoBuyConn = nil
        end
    end

    -- ---- Keybind listener ----
    UIS.InputBegan:Connect(function(input, gpe)
        if gpe then return end
        if input.KeyCode == FX.AnchorKey then
            FX.Anchor = not FX.Anchor
            if FX.Anchor then StartAnchor() else StopAnchor() end
        elseif input.KeyCode == FX.InstantBuyKey then
            FX.InstantBuy = not FX.InstantBuy
            if FX.InstantBuy then StartInstantBuy() else StopInstantBuy() end
        elseif input.KeyCode == FX.AutoBuyKey then
            FX.AutoBuy = not FX.AutoBuy
            if FX.AutoBuy then StartAutoBuy() else StopAutoBuy() end
        end
    end)

    -- ---- UI build ----
    local function buildFxTab()
        local pageFn = _G.__SkibidiPage
        local C      = _G.__SkibidiC
        if not pageFn or not C then return end

        local fxPage = pageFn("Fx Admin")
        if not fxPage then return end

        local scroll = safeNew("ScrollingFrame", {
            Parent = fxPage,
            Size = UDim2.new(1, 0, 1, 0),
            BackgroundTransparency = 1,
            ScrollBarThickness = 3,
            ScrollBarImageColor3 = C.Faint,
            CanvasSize = UDim2.new(0, 0, 0, 0),
            AutomaticCanvasSize = Enum.AutomaticSize.Y,
        })
        safeNew("UIListLayout", { Parent = scroll, Padding = UDim.new(0, 4), SortOrder = Enum.SortOrder.LayoutOrder })
        safeNew("UIPadding", { Parent = scroll, PaddingLeft = UDim.new(0, 6), PaddingRight = UDim.new(0, 6), PaddingTop = UDim.new(0, 6) })

        local toggleStates = {}

        local function toggleRow(title, desc, key, fxKey, startFn, stopFn, order)
            local row = safeNew("Frame", {
                Parent = scroll,
                BackgroundColor3 = C.Panel,
                Size = UDim2.new(1, 0, 0, 58),
                LayoutOrder = order,
                ClipsDescendants = false,
            })
            safeNew("UICorner", { Parent = row, CornerRadius = UDim.new(0, 6) })

            safeNew("TextLabel", {
                Parent = row,
                Position = UDim2.new(0, 10, 0, 8),
                Size = UDim2.new(0.6, 0, 0, 16),
                BackgroundTransparency = 1,
                Text = title .. "  [" .. key .. "]",
                TextColor3 = C.Text,
                TextSize = 11,
                Font = Enum.Font.GothamBold,
                TextXAlignment = Enum.TextXAlignment.Left,
            })
            safeNew("TextLabel", {
                Parent = row,
                Position = UDim2.new(0, 10, 0, 26),
                Size = UDim2.new(0.75, 0, 0, 24),
                BackgroundTransparency = 1,
                Text = desc,
                TextColor3 = C.Sub,
                TextSize = 9,
                Font = Enum.Font.GothamMedium,
                TextXAlignment = Enum.TextXAlignment.Left,
                TextWrapped = true,
            })

            -- toggle pill
            local pillBg = safeNew("TextButton", {
                Parent = row,
                Position = UDim2.new(1, -54, 0.5, -11),
                Size = UDim2.new(0, 44, 0, 22),
                BackgroundColor3 = C.Faint,
                Text = "",
                AutoButtonColor = false,
            })
            safeNew("UICorner", { Parent = pillBg, CornerRadius = UDim.new(1, 0) })
            local knob = safeNew("Frame", {
                Parent = pillBg,
                Position = UDim2.new(0, 2, 0.5, -9),
                Size = UDim2.new(0, 18, 0, 18),
                BackgroundColor3 = Color3.new(1,1,1),
            })
            safeNew("UICorner", { Parent = knob, CornerRadius = UDim.new(1, 0) })

            local TS = game:GetService("TweenService")
            local function setState(on)
                FX[fxKey] = on
                toggleStates[fxKey] = on
                local destPos = on and UDim2.new(1, -20, 0.5, -9) or UDim2.new(0, 2, 0.5, -9)
                local destCol = on and C.Green or C.Faint
                TS:Create(knob, TweenInfo.new(0.15), { Position = destPos }):Play()
                TS:Create(pillBg, TweenInfo.new(0.15), { BackgroundColor3 = destCol }):Play()
                if on then startFn() else stopFn() end
            end

            pillBg.MouseButton1Click:Connect(function()
                setState(not (toggleStates[fxKey] or false))
            end)
        end

        toggleRow("Anchor", "Freeze your character in place (also works mid-air)",
            "F", "Anchor", StartAnchor, StopAnchor, 1)
        toggleRow("Instant Buy", "Set HoldDuration=0 on all ProximityPrompts",
            "H", "InstantBuy", StartInstantBuy, StopInstantBuy, 2)
        toggleRow("Auto Buy", "Auto-fire nearby ProximityPrompts (< 15 studs)",
            "G", "AutoBuy", StartAutoBuy, StopAutoBuy, 3)

        -- Nearest prompt panel
        local nearPanel = safeNew("Frame", {
            Parent = scroll,
            BackgroundColor3 = C.Panel,
            Size = UDim2.new(1, 0, 0, 72),
            LayoutOrder = 4,
        })
        safeNew("UICorner", { Parent = nearPanel, CornerRadius = UDim.new(0, 6) })
        safeNew("TextLabel", {
            Parent = nearPanel,
            Position = UDim2.new(0, 10, 0, 6),
            Size = UDim2.new(1, -20, 0, 14),
            BackgroundTransparency = 1,
            Text = "NEAREST PROMPT",
            TextColor3 = C.Sub,
            TextSize = 9,
            Font = Enum.Font.GothamBold,
            TextXAlignment = Enum.TextXAlignment.Left,
        })
        local nearLabel = safeNew("TextLabel", {
            Parent = nearPanel,
            Position = UDim2.new(0, 10, 0, 22),
            Size = UDim2.new(1, -20, 0, 42),
            BackgroundTransparency = 1,
            Text = "none",
            TextColor3 = C.Text,
            TextSize = 10,
            Font = Enum.Font.GothamMedium,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextWrapped = true,
        })

        -- Scan nearest prompt every 2s
        task.spawn(function()
            while true do
                task.wait(2)
                pcall(function()
                    local lp = game:GetService("Players").LocalPlayer
                    local char = lp and lp.Character
                    local root = char and char:FindFirstChild("HumanoidRootPart")
                    if not root then nearLabel.Text = "no character"; return end
                    local best, bestDist = nil, math.huge
                    for _, pp in ipairs(WS:GetDescendants()) do
                        if pp:IsA("ProximityPrompt") then
                            local pos = GetPromptPosition(pp)
                            if pos then
                                local d = (root.Position - pos).Magnitude
                                if d < bestDist then bestDist = d; best = pp end
                            end
                        end
                    end
                    if best then
                        local model = GetPromptModel(best)
                        nearLabel.Text = string.format("[%.1f] %s › %s",
                            bestDist,
                            model and model.Name or "?",
                            best.ActionText ~= "" and best.ActionText or best.ObjectText)
                    else
                        nearLabel.Text = "none"
                    end
                end)
            end
        end)
    end

    local function tryBuildFx()
        if _G.__SkibidiPage then
            buildFxTab()
        else
            task.delay(2, tryBuildFx)
        end
    end
    task.spawn(tryBuildFx)
end

