    }
    iconButton(348, fxIcon)  -- y=348

    -- Wire clicks → selectPage
    local rail = _G.__SkibidiRail
    if rail then
        for _, btn in ipairs(rail:GetChildren()) do
            if btn:IsA("ImageButton") or btn:IsA("TextButton") then
                if math.abs(btn.Position.Y.Offset - 308) < 2 then
                    btn.MouseButton1Click:Connect(function()
                        if selectPage then selectPage("Weekly OG", true) end
