-- ============================================================
-- SECTION 8: IMPROVED RIDDLER RESOLUTION ENGINE
-- Wraps existing riddler with Central Time, wiki fallback,
-- math evaluator, multi-question splitter, DYNAMIC dates
-- ============================================================
task.spawn(function()
    local t0 = os.clock()
    while not _G.__RiddlerLookup and (os.clock() - t0) < 20 do task.wait(0.5) end

    -- Dynamic date resolver (Central Time)
    if not _G.__RiddlerResolveDynamic then
        local DAY_NAMES   = {"Sunday","Monday","Tuesday","Wednesday","Thursday","Friday","Saturday"}
        local MONTH_NAMES = {"January","February","March","April","May","June",
                             "July","August","September","October","November","December"}

        local function riddlerDaysUntil(month, day)
            local now  = _G.__RiddlerNow()
            local ct   = _G.__RiddlerCT(now)
            local thisY = ct.year
            local target = os.time({ year=thisY, month=month, day=day, hour=0, min=0, sec=0 })
            if target <= now then
                target = os.time({ year=thisY+1, month=month, day=day, hour=0, min=0, sec=0 })
            end
            local days = math.ceil((target - now) / 86400)
            return tostring(days)
        end

        _G.__RiddlerResolveDynamic = function(key)
            local k = tostring(key or ""):lower():gsub("[^%w%s]"," ")
            local now = _G.__RiddlerNow()
            local ct  = _G.__RiddlerCT(now)

            -- running mutations
            if k:find("mutation") and (k:find("running") or k:find("active") or k:find("current")) then
                local ok, muts = pcall(function()
                    return _G.__RiddlerRunningMutations and _G.__RiddlerRunningMutations() or {}
                end)
                if ok and muts and #muts > 0 then
                    return table.concat(muts, " and "):upper():gsub("[^%w]","")
                end
                return "NONE"
            end

            -- countdown timers
            if k:find("until halloween") or k:find("until october 31") then return riddlerDaysUntil(10, 31) end
            if k:find("until christmas") or k:find("until december 25") then return riddlerDaysUntil(12, 25) end
            if k:find("until new year") then return riddlerDaysUntil(1, 1) end
            if k:find("until 4th of july") or k:find("independence day") then return riddlerDaysUntil(7, 4) end
            if k:find("until valentine") then return riddlerDaysUntil(2, 14) end

            -- yesterday / tomorrow
            if k:find("yesterday") then
                local yd = os.time({ year=ct.year, month=ct.month, day=ct.day-1, hour=12 })
                local yct = _G.__RiddlerCT(yd)
                return string.format("%s %s %d %d",
                    DAY_NAMES[yct.wday], MONTH_NAMES[yct.month], yct.day, yct.year):upper():gsub("[^%w]","")
            end
            if k:find("tomorrow") then
                local td = os.time({ year=ct.year, month=ct.month, day=ct.day+1, hour=12 })
                local tct = _G.__RiddlerCT(td)
                return string.format("%s %s %d %d",
                    DAY_NAMES[tct.wday], MONTH_NAMES[tct.month], tct.day, tct.year):upper():gsub("[^%w]","")
            end

            -- time zone
            if k:find("time zone") or k:find("timezone") then return "CENTRAL" end

            -- current time
            if k:find("time") and not k:find("date") and not k:find("day") and not k:find("month") and not k:find("year") then
                local h = ct.hour % 12
                if h == 0 then h = 12 end
                local ampm = ct.hour >= 12 and "PM" or "AM"
                local tzn = (ct.offset == -5) and "CDT" or "CST"
                return string.format("%d:%02d%s%s", h, ct.min, ampm, tzn):upper():gsub("[^%w]","")
            end

            -- day of month
            if k:find("day of the month") or k:find("day number") then return tostring(ct.day) end

            -- day of week
            if k:find("day of the week") or k:find("what day") then return DAY_NAMES[ct.wday]:upper() end

            -- month
            if k:find("month") and not k:find("date") and not k:find("day") then
                return MONTH_NAMES[ct.month]:upper()
            end

            -- year
            if k:find("year") then return tostring(ct.year) end

            -- season
            if k:find("season") then
                local m = ct.month
                if m >= 3 and m <= 5 then return "SPRING"
                elseif m >= 6 and m <= 8 then return "SUMMER"
                elseif m >= 9 and m <= 11 then return "FALL"
                else return "WINTER" end
            end

            -- full date / today
            if k:find("date") or k:find("today") then
                return string.format("%s %s %d %d",
                    DAY_NAMES[ct.wday], MONTH_NAMES[ct.month], ct.day, ct.year
                ):upper():gsub("[^%w]","")
            end

            return nil
        end
    end

    -- Upgrade __RiddlerLookup to also try DYNAMIC via our resolver
    local origLookup = _G.__RiddlerLookup
    if origLookup then
        _G.__RiddlerLookup = function(text)
            local ans, key = origLookup(text)
            if ans == "DYNAMIC" then
                local dyn = pcall(_G.__RiddlerResolveDynamic, text)
                if dyn then return dyn, key end
            end
            return ans, key
        end
    end
end)

-- ============================================================
-- SECTION 9: HARDENED REDEEM WALL
-- Patches the multi-layer click chain with extra robustness:
-- - Mutex guard prevents double-fire
-- - 6th method: direct FireServer on RedeemCode RE
-- - Better TextBox resolution via getconnections upvalue scan
-- ============================================================
task.spawn(function()
    -- Wait for the redeem function to be published on _G
    local t0 = os.clock()
    while not _G.__SkibidiRedeem and (os.clock() - t0) < 20 do task.wait(0.5) end

    local origRedeem = _G.__SkibidiRedeem
    if not origRedeem then return end

    local redeemLock = false
    _G.__SkibidiRedeem = function(code)
        if redeemLock then return false, "busy" end
        redeemLock = true
        local ok, err = pcall(origRedeem, code)
        -- layer 6 fallback: direct RE fire
        if not ok or err then
            pcall(function()
                local RS = game:GetService("ReplicatedStorage")
                local net = RS:FindFirstChild("Packages")
                net = net and net:FindFirstChild("Net")
                -- try common remote names
                for _, rName in ipairs({ "RedeemCode", "Redeem", "CodeRedeem", "ClaimCode" }) do
                    local re = net and net:FindFirstChild(rName) or RS:FindFirstChild(rName)
                    if re and (re:IsA("RemoteEvent") or re:IsA("RemoteFunction")) then
                        if re:IsA("RemoteFunction") then
                            re:InvokeServer(tostring(code))
                        else
                            re:FireServer(tostring(code))
                        end
                        break
                    end
                end
            end)
        end
        task.delay(0.5, function() redeemLock = false end)
        return ok, err
    end
end)

-- ============================================================
-- SECTION 10: WIKI LOOKUP INTEGRATION
-- Provides __RiddlerFetchWiki for the resolution engine
-- Sources: stealarot.com, sabwiki, fandom + 7 fallbacks
-- ============================================================
if not _G.__RiddlerFetchWiki then
    local SAB_SOURCES = {
        { name="stealarot",     fmt="https://stealarot.com/brainrot/%s" },
        { name="sabwiki",       fmt="https://stealabrainrot.wiki/wiki/%s" },
        { name="fandom",        fmt="https://stealabrainrot.fandom.com/wiki/%s" },
        { name="stealarot-s",   fmt="https://stealarot.com/search?q=%s" },
        { name="sabvalues",     fmt="https://sabvalues.com/brainrot/%s" },
        { name="sabtracker",    fmt="https://stealabrainrottracker.com/brainrot/%s" },
        { name="fandom-mut",    fmt="https://stealabrainrot.fandom.com/wiki/%s_(Mutation)" },
        { name="fandom-event",  fmt="https://stealabrainrot.fandom.com/wiki/%s_(Event)" },
        { name="gg-fandom",     fmt="https://steal-a-brainrot.fandom.com/wiki/%s" },
        { name="sabwiki-search",fmt="https://stealabrainrot.wiki/w/index.php?search=%s" },
    }

    local function httpGet(url)
        local fn = (syn and syn.request) or (http and http.request) or http_request or request
        if not fn then return nil, "no http" end
        local ok, res = pcall(fn, {
            Url = url, Method = "GET",
            Headers = { ["User-Agent"] = "Mozilla/5.0" }
        })
        if not ok or not res then return nil, "failed" end
        if res.StatusCode and res.StatusCode >= 400 then return nil, "http "..res.StatusCode end
        return res.Body or res.body or "", nil
    end

    local function slugify(query)
        return tostring(query or ""):lower()
            :gsub("[^%w%s%-]", "")
            :gsub("%s+", "_")
            :gsub("_+", "_")
    end

    _G.__RiddlerFetchWiki = function(query)
        local slug = slugify(query)
        local lastErr
        for _, src in ipairs(SAB_SOURCES) do
            local url = src.fmt:format(slug)
            local body, err = httpGet(url)
            if body and #body > 100 then
                -- crude: check page actually has content about the query
                local flat = body:lower():gsub("[^%w%s]", " ")
                local qFlat = query:lower():gsub("[^%w%s]", " ")
                local firstWord = qFlat:match("^(%a+)") or ""
                if #firstWord < 3 or flat:find(firstWord, 1, true) then
                    return body, url
                end
            end
            lastErr = err or "empty"
        end
        return nil, lastErr
    end
end

