-- ============================================================
-- PERFORMANCE + UI POLISH v1
-- Keeps every existing option and page; only caches hot lookups
-- and applies a new visual shell to the already-built interface.
-- ============================================================
do
    -- Exact-question memoization: local answers are deterministic and the
    -- original resolver remains the source of truth for cache misses.
    local originalLookup = RiddleEngine and RiddleEngine.lookup
    if originalLookup and not RiddleEngine.__fastLookup then
        local memo, order, LIMIT = {}, {}, 256
        local function memoKey(question)
            return RiddleEngine.norm(tostring(question or ""))
        end
        RiddleEngine.lookup = function(question)
            local key = memoKey(question)
            local cached = memo[key]
            if cached ~= nil then return cached end
            local result = originalLookup(question)
            memo[key] = result or false
            order[#order + 1] = key
            if #order > LIMIT then
                local old = table.remove(order, 1)
                memo[old] = nil
            end
            return result
        end
        RiddleEngine.__fastLookup = true
        RiddleEngine.clearFastLookup = function()
            table.clear(memo)
            table.clear(order)
        end
    end

    -- New GUI skin: no controls are removed or renamed. Existing pages,
    -- toggles, sliders, logs and buttons stay in place and keep their links.
    task.defer(function()
        local player = game:GetService("Players").LocalPlayer
        local roots = {
            game:GetService("CoreGui"):FindFirstChild("SkibidiRedeemerUI"),
            game:GetService("CoreGui"):FindFirstChild("SkibidiRedeemer"),
            player and player:FindFirstChildOfClass("PlayerGui") and player.PlayerGui:FindFirstChild("SkibidiRedeemerUI"),
            player and player:FindFirstChildOfClass("PlayerGui") and player.PlayerGui:FindFirstChild("SkibidiRedeemer"),
        }
        local gui
        for _, candidate in ipairs(roots) do if candidate then gui = candidate break end end
        if not gui or gui:GetAttribute("ModernShellApplied") then return end
        gui:SetAttribute("ModernShellApplied", true)

        local function recolor(root)
            for _, obj in ipairs(root:GetDescendants()) do
                if obj:IsA("Frame") then
                    local n = string.lower(obj.Name)
                    if n:find("rail") or n:find("sidebar") then
                        obj.BackgroundColor3 = Color3.fromRGB(15, 17, 22)
                    elseif obj.BackgroundTransparency < 1 then
                        obj.BackgroundColor3 = Color3.fromRGB(24, 27, 34)
                    end
                elseif obj:IsA("TextLabel") or obj:IsA("TextButton") or obj:IsA("TextBox") then
                    obj.TextColor3 = Color3.fromRGB(238, 242, 247)
                    if obj:IsA("TextButton") then obj.AutoButtonColor = false end
                elseif obj:IsA("UIStroke") then
                    obj.Color = Color3.fromRGB(60, 70, 86)
                    obj.Transparency = 0.15
                end
            end
        end
        local rootFrame = gui:FindFirstChild("Window", true) or gui:FindFirstChildOfClass("Frame")
        if rootFrame then
            rootFrame.BackgroundColor3 = Color3.fromRGB(11, 13, 17)
            rootFrame.Size = UDim2.new(0, 520, 0, math.max(rootFrame.Size.Y.Offset, 400))
            recolor(rootFrame)
        end
    end)
end

